// Check checks a host's SSL certificate
func (s *SSLChecker) Check(ctx context.Context, component config.ComponentConfig) ComponentStatus {
	result := ComponentStatus{
		Name:      component.Name,
		Type:      TypeSSL,
		Target:    component.Target,
		Timestamp: time.Now(),
	}

	if component.Target == "" {
		result.Status = StatusError
		result.Error = "target not configured"
		return result
	}

	// Measure connection time
	start := time.Now()
	certs, err := FetchCertificateChain(component.Target, s.timeout)
	result.ResponseTime = time.Since(start)

	if err != nil {
		result.Status = StatusDown
		result.Error = err.Error()
		return result
	}
	if len(certs) == 0 {
		result.Status = StatusError
		result.Error = "no certificates found"
		return result
	}

	// Use leaf certificate (first in chain)
	cert := certs[0]

	// Extract certificate data
	notAfter := cert.NotAfter
	issuer := cert.Issuer.CommonName
	if issuer == "" {
		// Fallback to Organization if CommonName is empty
		if len(cert.Issuer.Organization) > 0 {
			issuer = cert.Issuer.Organization[0]
		} else {
			issuer = "Unknown"
		}
	}
	daysLeft := int(time.Until(notAfter).Hours() / 24)

	// Populate SSL-specific fields
	result.SSLExpires = &notAfter
	result.SSLDaysLeft = &daysLeft
	result.SSLIssuer = issuer

	// Determine status based on days left
	if daysLeft < 0 {
		result.Status = StatusError
		result.Error = "certificate expired"
	} else if daysLeft < 7 {
		result.Status = StatusError
		result.Error = fmt.Sprintf("expires in %d days", daysLeft)
	} else if daysLeft <= CertRenewWindowDays {
		result.Status = StatusWarning
		result.Error = fmt.Sprintf("expires in %d days", daysLeft)
	} else {
		result.Status = StatusOK
	}

	return result
}

// Visible returns what is on screen, in the order it is on screen.
func (m *Model[T]) Visible() []T { return m.visible }

// Selected returns the item under the cursor. The bool is false when there is
// nothing to select, which is the only case a caller has to handle.
func (m *Model[T]) Selected() (T, bool) {
	cursor := m.table.Cursor()
	if cursor < 0 || cursor >= len(m.visible) {
		var zero T
		return zero, false
	}
	return m.visible[cursor], true
}

// Cursor returns the selected row index.
func (m *Model[T]) Cursor() int { return m.table.Cursor() }

// SetCursor puts the cursor on a row, clamped to what exists. Views that
// remember a position across a reload — workspaces restores one per directory
// level on the way back up — call this; nothing else should need it.
func (m *Model[T]) SetCursor(i int) {
	if len(m.visible) == 0 {
		return
	}
	m.table.SetCursor(min(max(i, 0), len(m.visible)-1))
	m.afterCursorMove()
}

