// FooterMessage holds the current message, its level and its identity.
type FooterMessage struct {
	text     string
	level    Level
	id       uint64
	blinkOff bool
}

// Info, Warn and Error set the message and return its expiry timer. Call them
// from Update() and return the Cmd — a message set without its timer never
// clears (Rule 128).
func (f *FooterMessage) Info(text string) tea.Cmd  { return f.set(text, LevelInfo) }
func (f *FooterMessage) Warn(text string) tea.Cmd  { return f.set(text, LevelWarning) }
func (f *FooterMessage) Error(text string) tea.Cmd { return f.set(text, LevelError) }

func (f *FooterMessage) set(text string, level Level) tea.Cmd {
	if text == "" {
		f.Clear()
		return nil
	}
	f.text = text
	f.level = level
	f.id = footerMsgSeq.Add(1)

	id := f.id
	return tea.Tick(FooterMsgDuration, func(time.Time) tea.Msg {
		return ClearFooterMsg{ID: id}
	})
}

// Clear removes the message now, without waiting for its timer.
func (f *FooterMessage) Clear() {
	f.text = ""
	f.level = LevelInfo
	f.id = 0
}

// Handle consumes what the component owns and reports whether it did: a
// ClearFooterMsg addressed to the current message, and a PostFooterMsg from the
// router. A stale expiry is dropped, and so is one belonging to another view:
// both leave the message on screen for the time it was given.
func (f *FooterMessage) Handle(msg tea.Msg) bool {
	switch msg := msg.(type) {
	case PostFooterMsg:
		// Adopted whole, ID included: the timer that will expire it was built
		// with that ID by the sender, and re-numbering it here would leave a
		// message nothing ever clears.
		f.text = msg.Text
		f.level = msg.Level
		f.id = msg.ID
		return true

	case ClearFooterMsg:
		if f.id == 0 || msg.ID != f.id {
			return false
		}
		f.Clear()
		return true
	}
	return false
}

// SetBlinkPhase sets the phase the activity dot renders with. Read at render;
// nothing is rebuilt. Without a call the dot is steady on.

// Init starts the application
func (m Model) Init() tea.Cmd {
	return tea.Batch(
		tickCmd(),
		checkComponents(m.config),
	)
}

// Update handles messages and updates the state
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmds []tea.Cmd

	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.resize(msg.Width, msg.Height)

	case tea.KeyPressMsg:
		return m.handleInputKeyMsg(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)

	case TickMsg:
		return m.handleTick()

	case jobs.FrameMsg:
		m.footer.SetBlinkPhase(msg.Blink)

	case CheckCompleteMsg:
		return m.handleCheckComplete(msg)

	case components.ComponentFormSubmitMsg:
		return m.handleComponentFormSubmit(msg)

	case sharedcomponents.ConfirmModalYesMsg:
		return m.handleConfirmDelete()

	case sharedcomponents.ConfirmModalNoMsg:
		// Cancel deletion
		m.confirmModal = nil

		m.confirmModal = nil

	case ComponentSavedMsg:
		return m.handleComponentSaved(msg)

	case ComponentDeletedMsg:
		return m.handleComponentDeleted(msg)
	}

	// Update the active table if not in form/confirmation mode
	if m.componentForm == nil && m.confirmModal == nil {
		cmds = append(cmds, m.getCurrentTable().Update(msg))
	}

	return m, tea.Batch(cmds...)
}

// handleTick processes tick messages for auto-refresh timing
func (m Model) handleTick() (tea.Model, tea.Cmd) {
	// Refresh the table to update "Last Check"
	if len(m.components) > 0 {
		m.updateTable()
	}

	// Check whether a check is due
	if m.autoRefresh && !m.checking && time.Now().After(m.nextCheck) {
		m.checking = true
		// An auto-refresh refills a table that is already on screen: no dot.
		m.quietCheck = !m.firstCheck
		return m, tea.Batch(
			tickCmd(),
			checkComponents(m.config),
		)
	}
	return m, tickCmd()
}

// handleCheckComplete processes completed component checks
